$name=$map[$slug]??ucwords(str_replace('-',' ',$slug));
$title="Alanya $name | İşletme Rehberi - AlanyaNow";
$desc="Alanya'da $name arayanlar için Google Maps'te 4.0 ve üzeri puan görünen işletmeleri ve AlanyaNow'a manuel eklenen doğrulanmış işletmeleri keşfedin.";
$dataFile=__DIR__.'/data/google-4-plus-businesses.json';
$all=is_file($dataFile)?json_decode(file_get_contents($dataFile),true):[];
$businesses=$all[$slug]??[];
$businesses=array_values(array_filter($businesses,function($b){
  $manual=isset($b['source']) && $b['source']==='AlanyaNow manuel kayıt';
  $rated=isset($b['rating']) && $b['rating']!==null && (float)$b['rating']>=4.0;
  return $manual || $rated;
}));
usort($businesses,function($a,$b){
  $am=isset($a['source'])&&$a['source']==='AlanyaNow manuel kayıt';
  $bm=isset($b['source'])&&$b['source']==='AlanyaNow manuel kayıt';
  if($am!==$bm) return $bm<=>$am;
  return (($b['rating']??0)<=>($a['rating']??0)) ?: (($b['reviews']??0)<=>($a['reviews']??0));
});
$canonical='https://alanyanow.com/alanya-'.$slug.'.html';
function stars($rating){$n=(int)round((float)$rating);return str_repeat('★',$n).str_repeat('☆',5-$n);}
function mapsUrl($b){return 'https://www.google.com/maps/search/?api=1&query='.rawurlencode(($b['name']??'').' '.($b['address']??''));}
